<?php
declare(strict_types=1); require_once __DIR__.DIRECTORY_SEPARATOR.'auth.php'; admin_require_login(); send_security_headers(); header('Content-Type: text/html; charset=utf-8'); $p=db_connection(); $term=is_string($_GET['q']??null)?trim($_GET['q']):''; $page=filter_var($_GET['page']??'1',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:1; $limit=20; $where=$term===''?'':' WHERE v.name LIKE :term'; $c=$p->prepare('SELECT COUNT(*) FROM visitors v'.$where); if($term!=='')$c->execute([':term'=>'%'.$term.'%']);else$c->execute(); $total=(int)$c->fetchColumn(); $pages=max(1,(int)ceil($total/$limit));$page=min($page,$pages);$q=$p->prepare('SELECT v.id,v.name,v.created_at,COUNT(ph.id) photo_count FROM visitors v LEFT JOIN photos ph ON ph.visitor_id=v.id'.($term!==''?' WHERE v.name LIKE :term':'').' GROUP BY v.id,v.name,v.created_at ORDER BY v.id DESC LIMIT :lim OFFSET :off');if($term!=='')$q->bindValue(':term','%'.$term.'%',PDO::PARAM_STR);$q->bindValue(':lim',$limit,PDO::PARAM_INT);$q->bindValue(':off',($page-1)*$limit,PDO::PARAM_INT);$q->execute();$rows=$q->fetchAll();echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Visitors</title></head><body><h1>Visitors</h1><p><a href="index.php">Dashboard</a></p><form method="get"><label>Search by name <input name="q" maxlength="100" value="'.admin_e($term).'"></label><button>Search</button></form><p>'.$total.' visitor(s); page '.$page.' of '.$pages.'.</p><table border="1"><tr><th>Name</th><th>Registered</th><th>Photos</th><th>Photo list</th></tr>';foreach($rows as $v)echo '<tr><td>'.admin_e($v['name']).'</td><td>'.admin_e($v['created_at']).'</td><td>'.(int)$v['photo_count'].'</td><td><a href="photos.php?visitor='.(int)$v['id'].'">View photos</a></td></tr>';if(!$rows)echo '<tr><td colspan="4">No visitors found.</td></tr>';echo '</table><nav>';for($i=1;$i<=$pages;$i++)echo ' <a href="?q='.rawurlencode($term).'&amp;page='.$i.'">'.$i.'</a> ';echo '</nav></body></html>';
